#include "TestHarness.h"
#include "OptimizationFixture.h"
#include <minuvex/Viewer.h>
#include <minuvex/EditorDocument.h>
#include <atomic>
#include <thread>
using namespace test;
namespace {
lv::AssetLoadSnapshot Await(lv::AssetLoader& loader,lv::AssetLoadId job) {const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(5);while (std::chrono::steady_clock::now()<end) {const auto s=loader.Poll(job);if (!s) {throw std::runtime_error(s.Error().Message);}if (s.Value().State != lv::AssetLoadState::Importing && s.Value().State != lv::AssetLoadState::Queued) {return s.Value();}std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("Async import timed out.");}
std::vector<std::array<float,9>> Triangles(const lv::MeshData& mesh) {std::vector<std::array<float,9>> result;for (std::size_t i=0;i<mesh.Indices.size();i+=3) {std::array<float,9> t;for (unsigned j=0;j<3;++j) {for (unsigned c=0;c<3;++c) {t[j*3+c]=mesh.Vertices[mesh.Indices[i+j]].Position[c];}}result.push_back(t);}std::sort(result.begin(),result.end());return result;}
}
void TestOptimizationContracts() {
    const auto mesh=OptimizationGrid(true);const auto levels=lv::GenerateMeshLods(mesh);Check(levels.size() == 3 && levels.back().Indices.size()<=mesh.Indices.size()/4,"attribute-aware LOD reaches useful reductions without dropping whole disconnected triangles");
    const auto optimized=lv::OptimizeMesh(mesh,levels);Check(Triangles(mesh)==Triangles(optimized.Geometry) && optimized.Geometry.Vertices.size()==mesh.Vertices.size(),"cache/fetch optimization preserves geometry and source vertex population");Check(optimized.CacheMissesAfter<optimized.CacheMissesBefore,"deterministic shuffled grid improves simulated vertex cache locality");
    bool attributes=true;for (const auto& v:optimized.Geometry.Vertices) {attributes&=Near(v.TexCoord[0],(v.Position[0]+1)*.5f) && Near(v.TexCoord[1],(v.Position[1]+1)*.5f);}Check(attributes,"fetch remapping retains UV/position associations");
    Check(lv::SelectMeshLod(300,0,3)==0 && lv::SelectMeshLod(10,0,3)==3 && lv::SelectMeshLod(300,2,3)==2,"screen-space LOD selection supports explicit bias");Rejects([] {(void)lv::SelectMeshLod(1,5,3);},"invalid LOD bias rejected");
    Check(lv::TextureMipBytes(256,256,true)<lv::TextureMipBytes(256,256)/3 && lv::TextureMipBytes(1,1,true)==16,"block compression estimates include minimum block-sized tail mips");
    lv::AssetLoader loader;TemporaryDirectory temp;const auto file=temp.File("async.glb");Write(file,Read(Fixture("SharedBox.glb")));const auto job=loader.Submit(file);Check(bool(job),"async submit accepts a supported source");const auto done=Await(loader,job.Value());Check(done.State == lv::AssetLoadState::Ready && done.Model && !done.Failure,"worker publishes a validated immutable candidate");Check(loader.Forget(job.Value()).HasValue() && !loader.Poll(job.Value()),"forget releases terminal job ownership");
    const auto bad=temp.File("broken.glb");Write(bad,"invalid");const auto failed=loader.Submit(bad);const auto failure=Await(loader,failed.Value());Check(failure.State == lv::AssetLoadState::Failed && failure.Failure && !failure.Model,"worker failure is explicit without a partial published asset");(void)loader.Forget(failed.Value());
    struct Gate {std::atomic_bool Started=false,Released=false;};const auto gate=std::make_shared<Gate>();struct Release {std::shared_ptr<Gate> Value;~Release(){Value->Released=true;}} release{gate};lv::ImporterRegistry importers;const auto source=done.Model;
    importers.Register(".slow",[gate,source](const auto&,const auto&) {gate->Started=true;while (!gate->Released.load()) {std::this_thread::sleep_for(std::chrono::milliseconds(1));}return *source;});const auto slow=temp.File("slow.slow");Write(slow,"slow");const auto blocked=loader.Submit(slow,{},importers);
    const auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(5);while (!gate->Started && std::chrono::steady_clock::now()<deadline) {std::this_thread::sleep_for(std::chrono::milliseconds(1));}Check(gate->Started && loader.Cancel(blocked.Value()) && loader.Poll(blocked.Value()).Value().State == lv::AssetLoadState::Cancelled,"cancellation publishes immediately while a parser is still blocked");Check(loader.Forget(blocked.Value()).HasValue(),"cancelled running job can be forgotten safely");gate->Released=true;
    lv::Viewer viewer;const auto submitted=viewer.AddModelAsync(file);Check(submitted && viewer.GetScene().Size()==0,"Viewer async import does not mutate Scene before commit");const auto until=std::chrono::steady_clock::now()+std::chrono::seconds(5);while (viewer.GetAssetLoad(submitted.Value()).Value().State != lv::AssetLoadState::Ready && std::chrono::steady_clock::now()<until) {std::this_thread::sleep_for(std::chrono::milliseconds(1));}const auto object=viewer.CommitModelLoad(submitted.Value());Check(object && viewer.GetScene().Size()==1 && !viewer.GetAssetLoad(submitted.Value()),"owner-thread async commit publishes exactly once");
    const auto original=viewer.GetScene().GetObject(object.Value()).Model;Check(viewer.SetHotReload(true).HasValue(),"Viewer enables hot reload without starting a renderer");Write(file,"broken source changed");auto time=std::filesystem::last_write_time(file);std::filesystem::last_write_time(file,time+std::chrono::seconds(2));Check(viewer.SetHotReload(true).HasValue(),"enabling hot reload twice is idempotent and preserves pending change evidence");(void)viewer.PollHotReload(0);
    const auto retryEnd=std::chrono::steady_clock::now()+std::chrono::seconds(5);while (!viewer.GetAssetLoadError().Value() && std::chrono::steady_clock::now()<retryEnd) {(void)viewer.PollHotReload(.1);std::this_thread::sleep_for(std::chrono::milliseconds(1));}Check(viewer.GetAssetLoadError().Value().has_value() && viewer.GetScene().GetObject(object.Value()).Model==original,"failed hot reload retains the previous Scene asset and exposes the error");
    Write(file,Read(Fixture("SharedBox.glb")));std::filesystem::last_write_time(file,time+std::chrono::seconds(4));(void)viewer.PollHotReload(2);
    const auto reloadEnd=std::chrono::steady_clock::now()+std::chrono::seconds(5);while (viewer.GetScene().GetObject(object.Value()).Model == original && std::chrono::steady_clock::now()<reloadEnd) {(void)viewer.PollHotReload(2.1);std::this_thread::sleep_for(std::chrono::milliseconds(1));}Check(viewer.GetScene().GetObject(object.Value()).Model != original && viewer.GetScene().GetObject(object.Value()).Model->Id == original->Id,"repaired source hot reload publishes atomically with a stable Asset ID");
    lv::EditorDocument doc;const auto open=doc.OpenModel(Fixture("AnimatedRibbon.gltf"));Check(bool(open),"editor document loads animation fixture");(void)doc.PlayAnimation(open.Value(),0);(void)doc.SeekAnimation(open.Value(),.5);const auto before=doc.Assets().front();auto incompatible=std::make_shared<lv::ModelAsset>(*before);incompatible->Skeleton.Joints[1].Name+=" changed";incompatible->Skeleton.Signature=lv::SkeletonSignature(incompatible->Skeleton);
    Check(!doc.CommitReimport(before->Id,incompatible) && doc.Assets().front()==before && doc.GetScene().GetObject(open.Value()).Model==before && doc.GetScene().GetObject(open.Value()).Animation.Time()==.5,"incompatible prepared reload rolls back registry, instances and playhead");
    lv::AssetHotReload watcher;auto dependency=std::make_shared<lv::ModelAsset>(*done.Model);const auto missing=temp.File("restored.png");dependency->MissingDependencies.push_back(missing);watcher.Watch(dependency);Check(watcher.Poll(0).empty(),"watch registration establishes a baseline");Write(missing,"created");Check(watcher.Poll(1).size()==1 && watcher.Poll(1.5).empty() && watcher.Poll(2).empty(),"missing dependency restoration is detected once with rate limiting");
}
